	public static void addAddonToBlock(TFMProcess _process, TFMLogicBlock _block, TFMLogicBlockAddon _addon)
    {
        TFMProcessBlockAddons addons = TFMProcessBlockAddons::Find(_process, _block, _addon);

        if (addons || !_process.parmVersion())
        {
            return;
        }

        addons.ProcessID = _process.parmProcessName();
        addons.Version = _process.parmVersion();
        addons.BlockName = _block.parmName();
        addons.AddonClass = classId2Name(classIdGet(_addon));
        addons.insert();

	}

public static void removeAddonToBlock(TFMProcess _process, TFMLogicBlock _block, TFMLogicBlockAddon _addon)
{
    TFMProcessBlockAddons addons = TFMProcessBlockAddons::Find(_process, _block, _addon, true);

    if (!addons)
    {
        return;
    }
    ttsbegin;
    addons.delete();
    ttscommit;
}

public static TFMProcessBlockAddons Find(TFMProcess _process, TFMLogicBlock _block, TFMLogicBlockAddon _addon, boolean _selectForUpdate = false)
{
    TFMProcessBlockAddons addons;
    if (!_process.parmVersion())
    {
        return null;
    }
    if(_selectForUpdate)
    {
        select firstonly forupdate addons where addons.ProcessID == _process.parmProcessName() && addons.Version == _process.parmVersion() && addons.BlockName == _block.parmName() && addons.AddonClass == classId2Name(classIdGet(_addon));
    } 
    else
    {
        select firstonly addons where addons.ProcessID == _process.parmProcessName() && addons.Version == _process.parmVersion() && addons.BlockName == _block.parmName() && addons.AddonClass == classId2Name(classIdGet(_addon));
    }
    return addons;        
}
